package com.dndmaster.aigamemaster.application.rule;
import com.dndmaster.aigamemaster.application.GroundingViolationException; import java.util.*;
public final class GroundedRuleAnswerService{private final RuleAnswerModelPort model;public GroundedRuleAnswerService(RuleAnswerModelPort model){this.model=Objects.requireNonNull(model);}public RuleAnswerOutput compose(RuleAnswerRequest request){RuleAnswerOutput out=model.compose(request);if(out.evidenceStatus()!=request.evidenceStatus())throw new GroundingViolationException("model hid or changed evidence status");Set<Citation> allowed=request.evidence().stream().map(SourceEvidence::citation).collect(java.util.stream.Collectors.toUnmodifiableSet());if(out.evidenceStatus()==EvidenceStatus.SUFFICIENT){if(out.conclusion()==null||out.conclusion().isBlank()||out.conclusionCitations().isEmpty())throw new GroundingViolationException("uncited conclusion forbidden");validate(out.conclusionCitations(),allowed);if(!out.candidates().isEmpty())throw new GroundingViolationException("sufficient answer must not disclose conflicting candidates");}else{if(out.conclusion()!=null&&!out.conclusion().isBlank())throw new GroundingViolationException("uncertain evidence cannot produce conclusion");if(!out.uncertaintyDisclosed()||out.candidates().isEmpty())throw new GroundingViolationException("uncertainty and candidates must be disclosed");for(RuleCandidate c:out.candidates()){if(c.citations().isEmpty())throw new GroundingViolationException("candidate citation required");validate(c.citations(),allowed);}}return out;}private static void validate(List<Citation> citations,Set<Citation> allowed){if(citations.stream().anyMatch(c->!allowed.contains(c)))throw new GroundingViolationException("citation outside selected evidence");}}
